package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
import com.ruoyi.medical.contracts.*;import java.nio.file.*;import java.nio.file.attribute.PosixFilePermissions;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.concurrent.atomic.AtomicBoolean;
/** Real local process contract tests using explicit fixture executables, never a claimed provider tokenizer. */
class FormalTokenizerRunnerTest {
 @TempDir Path temp;static final String ID="00000000-0000-4000-8000-000000000001";
 FormalTokenizerRunner runner(String body,int maxOut,Duration timeout)throws Exception{Path p=temp.resolve("fixture.py");Files.writeString(p,"#!/usr/bin/python3\n"+body);Files.setPosixFilePermissions(p,PosixFilePermissions.fromString("rwx------"));return new FormalTokenizerRunner(new FormalTokenizerRunner.Configuration(true,p,WireValues.sha256(Files.readAllBytes(p)),ID,4096,maxOut,timeout));}
 String hash()throws Exception{return WireValues.sha256(Files.readAllBytes(temp.resolve("fixture.py")));}
 @Test void actualBoundedProcessBindsInputAndExecutable()throws Exception{var r=runner("import sys,json\nv=json.load(sys.stdin)\nprint(json.dumps(dict(schema_version='1.0.0',tokenizer_version=v['tokenizer_version'],input_sha256=v['input_sha256'],token_count='3',complete=True)))\n",2048,Duration.ofSeconds(2));byte[] b="{\"fixture\":true}".getBytes(StandardCharsets.UTF_8);var result=r.count(b,ID,hash(),()->false);assertEquals("3",result.tokenCount().toString());assertEquals(WireValues.sha256(b),result.inputSha256());assertEquals(hash(),result.executableSha256());}
 @Test void forgedInputDigestRejected()throws Exception{var r=runner("import sys,json\nv=json.load(sys.stdin)\nprint(json.dumps(dict(schema_version='1.0.0',tokenizer_version=v['tokenizer_version'],input_sha256='0'*64,token_count='3',complete=True)))\n",2048,Duration.ofSeconds(2));assertEquals(ErrorCode.CONTENT_MISMATCH,assertThrows(TenantAccessException.class,()->r.count(new byte[]{1},ID,hash(),()->false)).code());}
 @Test void cancelledBeforeProcessDoesNotRun()throws Exception{var r=runner("raise Exception('must not run')\n",2048,Duration.ofSeconds(2));assertEquals(ErrorCode.LEASE_STALE,assertThrows(TenantAccessException.class,()->r.count(new byte[]{1},ID,hash(),()->true)).code());}
 @Test void processDeadlineKillsHungFixture()throws Exception{var r=runner("import time\ntime.sleep(30)\n",2048,Duration.ofMillis(100));long start=System.nanoTime();assertEquals(ErrorCode.CONTEXT_LIMIT,assertThrows(TenantAccessException.class,()->r.count(new byte[]{1},ID,hash(),()->false)).code());assertTrue(Duration.ofNanos(System.nanoTime()-start).compareTo(Duration.ofSeconds(3))<0);}
 @Test void changedExecutableAndOversizeOutputFailClosed()throws Exception{var r=runner("print('x'*5000)\n",128,Duration.ofSeconds(2));String old=hash();assertThrows(Exception.class,()->r.count(new byte[]{1},ID,old,()->false));Files.writeString(temp.resolve("fixture.py"),"#!/usr/bin/python3\nprint('changed')\n");assertEquals(ErrorCode.CONTENT_MISMATCH,assertThrows(TenantAccessException.class,()->r.count(new byte[]{1},ID,old,()->false)).code());}
}
